class _PigeonCodec extends StandardMessageCodec {
  const _PigeonCodec();
  @override
  void writeValue(WriteBuffer buffer, Object? value) {
    if (value is int) {
      buffer.putUint8(4);
      buffer.putInt64(value);
    }    else if (value is LensOption) {
      buffer.putUint8(129);
      writeValue(buffer, value.encode());
    }    else if (value is RecordingMode) {
      buffer.putUint8(130);
      writeValue(buffer, value.encode());
    }    else if (value is ShootProfile) {
      buffer.putUint8(131);
      writeValue(buffer, value.encode());
    }    else if (value is ShootLens) {
      buffer.putUint8(132);
      writeValue(buffer, value.encode());
    }    else if (value is ProfileSettings) {
      buffer.putUint8(133);
      writeValue(buffer, value.encode());
    }    else if (value is PictureProfileInfo) {
      buffer.putUint8(134);
      writeValue(buffer, value.encode());
    }    else if (value is MediaClip) {
      buffer.putUint8(135);
      writeValue(buffer, value.encode());
    }    else if (value is MediaStorageInfo) {
      buffer.putUint8(136);
      writeValue(buffer, value.encode());
    }    else if (value is AudioInputOption) {
      buffer.putUint8(137);
      writeValue(buffer, value.encode());
    }    else if (value is AudioTelemetry) {
      buffer.putUint8(138);
      writeValue(buffer, value.encode());
    }    else if (value is CameraState) {
      buffer.putUint8(139);
      writeValue(buffer, value.encode());
    }    else if (value is CameraTelemetry) {
      buffer.putUint8(140);
      writeValue(buffer, value.encode());
    } else {
      super.writeValue(buffer, value);
    }
  }

  @override
  Object? readValueOfType(int type, ReadBuffer buffer) {
    switch (type) {
      case 129:
        return LensOption.decode(readValue(buffer)!);
      case 130:
        return RecordingMode.decode(readValue(buffer)!);
      case 131:
        return ShootProfile.decode(readValue(buffer)!);
      case 132:
        return ShootLens.decode(readValue(buffer)!);
      case 133:
        return ProfileSettings.decode(readValue(buffer)!);
      case 134:
        return PictureProfileInfo.decode(readValue(buffer)!);
      case 135:
        return MediaClip.decode(readValue(buffer)!);
      case 136:
        return MediaStorageInfo.decode(readValue(buffer)!);
      case 137:
        return AudioInputOption.decode(readValue(buffer)!);
      case 138:
        return AudioTelemetry.decode(readValue(buffer)!);
      case 139:
        return CameraState.decode(readValue(buffer)!);
      case 140:
        return CameraTelemetry.decode(readValue(buffer)!);
      default:
